from .core import *

def make(family,v,n):
    d=4+2*(v%3);a=1+v%(d-1);b=1+(v+1)%(d-1)
    x=F(a,d);y=F(b,d);w=1+v
    if family=='fraction_intro':
        tasks=[shade(a,d),choice('Какая дробь показана?',f'{a}/{d}',[f'{a}/{d}',f'{d}/{a}',f'{a+1}/{d}'],'Все части одного целого равны.',model=fraction(a,d)),number(f'В дроби {a}/{d} назови знаменатель.',d,'Знаменатель показывает число равных частей целого.'),number(f'В дроби {a}/{d} назови числитель.',a,'Числитель показывает число взятых частей.'),choice('Можно ли назвать две неравные части половинами?','Нет',['Да','Нет'],'Половины одного целого должны быть равны.'),number(f'Лента разделена на {d} равных частей. Взяли {a}. Какую долю ленты взяли?',x,'Запиши дробь через /.')]
        return package('Собери долю',['Дробь показывает, сколько равных частей целого взяли.','Числитель записывают над чертой, знаменатель — под ней.'],['Закрашены 3 части из 8 равных','Получаем дробь 3/8: три восьмых.'],'Нарисуй прямоугольник, раздели его на равные части и запиши свою дробь.',tasks)
    if family=='reduce':
        k=2+v%3;q=F(a,d)
        tasks=[choice(f'Сократи дробь {2*a}/{2*d} до несократимой.',f(q),[f(q),f'{2*a}/{2*d}',f'{a+1}/{d}'],'Раздели числитель и знаменатель на одно и то же число.'),number(f'Раздели числитель и знаменатель {3}/{9+3*v} на 3. Новый знаменатель?',3+v,'Делить нужно обе части дроби.'),choice('Можно ли сократить 3/5 на 2?','Нет',['Да','Нет'],'Нужен общий натуральный делитель числителя и знаменателя.'),number(f'{k}/{2*k} = 1/□. Какое число в окошке?',2,'Раздели числитель и знаменатель на '+str(k)+'.'),choice('Почему 2/4 = 1/2?','Обе записи задают половину',['Сумма цифр одинаковая','Обе записи задают половину','Знаменатели равны'],'Значение дроби при сокращении не меняется.',model=fraction(2,4)),number(f'Найди числитель несократимой дроби, равной {2*(v+2)}/{4*(v+2)}.',1,'Сначала найди общий делитель.')]
        return package('Дробь меняет одежду',['Умножение или деление обеих частей дроби на одно натуральное число не меняет её значения.','Сокращай до тех пор, пока у числителя и знаменателя не останется общего делителя больше 1.'],['Сократи 6/8','6/8 = 3/4: обе части разделили на 2.'],'Изобрази 2/4 и 1/2 на одинаковых полосках и объясни равенство.',tasks)
    if family=='new_denominator':
        k=2+v
        tasks=[shade(1,2),number(f'1/2 = □/{2*k}. Найди числитель.',k,'Во сколько раз увеличили знаменатель, во столько же увеличь числитель.'),number(f'2/3 = □/{3*k}. Найди числитель.',2*k,'Умножь обе части дроби на '+str(k)+'.'),choice('Что нужно сделать со знаменателем, если числитель умножили на 4?','Умножить на 4',['Прибавить 4','Умножить на 4','Не менять'],'Обе части дроби меняются одинаково.'),number(f'{a}/{d} = □/{d*3}. Найди числитель.',a*3,'Новый знаменатель в 3 раза больше.'),choice(f'Равны ли {a}/{d} и {a}/{d*2}?','Нет',['Да','Нет'],'Если изменить только знаменатель, изменится значение дроби.')]
        return package('Одинаковая доля — новая сетка',['Новый знаменатель должен быть кратен старому.','Дополнительный множитель применяют и к числителю, и к знаменателю.'],['Приведи 2/3 к знаменателю 12','12 ÷ 3 = 4. Получаем 8/12.'],'Запиши три разные дроби, равные 1/2.',tasks)
    if family=='proper':
        tasks=[choice(f'Дробь {a}/{d} правильная?','Да',['Да','Нет'],'У правильной дроби числитель меньше знаменателя.',model=fraction(a,d)),choice(f'Дробь {d+v}/{d} правильная?','Нет',['Да','Нет'],'У неправильной дроби числитель не меньше знаменателя.'),multi('Выбери все неправильные дроби.',['5/3','4/4'],['1/2','5/3','4/4','3/8'],'Дробь, равная 1, тоже неправильная.'),number(f'{d}/{d} = ?',1,'Все части вместе составляют одно целое.'),choice('Правильная положительная дробь расположена…','Между 0 и 1',['Левее 0','Между 0 и 1','Правее 1'],'Правильная дробь меньше единицы.'),choice(f'Сравни {d+1}/{d} и 1.','>',['<','>','='],'В дроби взято больше частей, чем требуется на целое.')]
        return package('По какую сторону единицы?',['У правильной дроби числитель меньше знаменателя.','Неправильная дробь больше или равна 1.'],['7/5','7 частей по 1/5 — это больше одного целого.'],'Размести примеры правильной дроби, дроби 1 и неправильной дроби на луче.',tasks)
    if family=='mixed':
        numerator=w*d+a
        tasks=[choice('Смешанное число состоит из…','Целой части и правильной дроби',['Двух целых чисел','Целой части и правильной дроби','Только знаменателя'],'Например, 2 1/3.'),number(f'В дроби {numerator}/{d} сколько целых?',w,'Раздели числитель на знаменатель: целая часть — частное.'),number(f'После выделения целых из {numerator}/{d} какой остаток?',a,'Остаток станет числителем дробной части.'),number(f'Запиши {w} {a}/{d} одной дробью.',F(numerator,d),'Целую часть умножь на знаменатель и прибавь числитель.'),choice('Как преобразовать 2 1/3?','(2 × 3 + 1)/3',['(2 + 1)/3','(2 × 3 + 1)/3','2/(1 + 3)'],'Знаменатель остаётся прежним.'),number(f'Запиши {w+1} 1/2 неправильной дробью.',F(2*(w+1)+1,2),'Проверь обратным выделением целых.')]
        return package('Сколько целых в дроби?',['Неправильная дробь может содержать несколько целых и остаток.','Смешанное число переводят в неправильную дробь, сохраняя знаменатель.'],['11/4','11 ÷ 4 = 2 (остаток 3). Значит, 11/4 = 2 3/4.'],'Изобрази 7/3 и запиши то же число в смешанном виде.',tasks)
    if family=='fraction_ray':
        dd=3+v%3;nn=1+v%(dd-1)
        tasks=[shade(1,dd),ray(nn,dd,dd*2),number(f'От 0 до 1 — {dd} равных промежутков. Длина одного промежутка?',F(1,dd),'Раздели единицу на число равных частей.'),ray(dd+nn,dd,dd*2),choice(f'Точка {dd+nn}/{dd} находится…','Между 1 и 2',['Между 0 и 1','Между 1 и 2','В точке 0'],'Сначала выдели целую часть.'),ray(2*dd-1,dd,dd*2)]
        return package('Дробные остановки',['Единичный отрезок делят на равные части по знаменателю дроби.','Для смешанного числа сначала отсчитай целые отрезки.'],['Отметь 3/4','Раздели отрезок 0–1 на 4 равные части, отсчитай 3 от нуля.'],'Построй в тетради луч и отметь 1/2, 3/2 и 2 1/2.',tasks)
    if family=='compare_fractions':
        p=F(1,2+v%3);q=F(2,3+v%4);sym='<' if p<q else '>' if p>q else '='
        tasks=[shade(1,2),number(f'1/2 = □/{2*(v+3)}. Найди числитель.',v+3,'Приведение к общему знаменателю делает доли одинаковыми.'),choice(f'{a}/{d} … {a+1}/{d}. Выбери знак.','<',['>','=','<'],'При равных знаменателях больше дробь с большим числителем.'),choice(f'{f(p)} … {f(q)}. Выбери знак.',sym,['<','>','='],'Приведи дроби к общему знаменателю и сравни числители.'),order('Упорядочь дроби по возрастанию.',['3/4','1/2','5/4','1/4'],'Сначала отдели числа меньше единицы от чисел больше единицы.'),choice(f'{w} 1/2 … {w} 1/3. Выбери знак.','>',['<','>','='],'Если целые части равны, сравни дробные.')]
        return package('Парад дробей',['Сравнивай одинаковые доли: приводи дроби к общему знаменателю.','У смешанных чисел сначала сравнивают целые части.'],['Сравни 1/2 и 2/3','1/2 = 3/6, 2/3 = 4/6. Поэтому 1/2 < 2/3.'],'Отметь две дроби на луче и объясни, какая больше.',tasks)
    if family in ['add_same','add_different','subtract_natural','mixed_operations','multiply','reciprocal','divide']:
        aa=F(1+v,3+v);bb=F(1,3+v);cc=F(1,2+v%3);whole=2+v
        if family=='add_same':
            tasks=[shade(1,4),expr(f'{f(aa)} + {f(bb)} = ?',aa,bb,'+','При одинаковых знаменателях складывают числители.'),choice(f'Какой знаменатель сохраняем при {1}/{d} + {2}/{d}?',str(d),[str(d),str(2*d),str(d+1)],'Знаменатели не складываются.'),expr(f'{f(aa+bb)} − {f(bb)} = ?',aa+bb,bb,'−','При одинаковых знаменателях вычитают числители.'),expr(f'От ленты длиной {f(aa+bb)} м отрезали {f(bb)} м. Сколько осталось?',aa+bb,bb,'−','Это задача на остаток.'),expr(f'{v+2}/{v+5} + 2/{v+5} = ?',F(v+2,v+5),F(2,v+5),'+','После сложения сократи результат, если возможно.')]
        elif family=='add_different':
            tasks=[number(f'1/2 = □/{2*(v+3)}. Заполни окошко.',v+3,'Найди дополнительный множитель.'),expr(f'{f(aa)} + {f(cc)} = ?',aa,cc,'+','Сначала приведи к общему знаменателю.'),expr(f'{f(aa+cc)} − {f(cc)} = ?',aa+cc,cc,'−','После приведения вычитай числители.'),choice('Вычитать числители дробей с разными знаменателями сразу…','Нельзя',['Можно','Нельзя'],'Сначала нужны одинаковые доли.'),expr(f'Прошли {f(aa)} км, затем {f(cc)} км. Какой общий путь?',aa,cc,'+','Складывай расстояния в одинаковых единицах.'),expr(f'{v+2}/{v+3} − 1/{2*(v+3)} = ?',F(v+2,v+3),F(1,2*(v+3)),'−','Общий знаменатель здесь '+str(2*(v+3))+'.')]
        elif family=='subtract_natural':
            tasks=[number(f'1 = □/{d}. Заполни окошко.',d,'Единица содержит все доли знаменателя.'),expr(f'1 − {a}/{d} = ?',1,x,'−','Представь единицу дробью с нужным знаменателем.'),expr(f'{whole} − 1/3 = ?',whole,F(1,3),'−','Одно целое можно заменить на 3/3.'),expr(f'{whole} − 3/4 = ?',whole,F(3,4),'−','Оставь целую часть и вычти дробные доли.'),expr(f'Было {whole} м ленты. Отрезали 2/5 м. Сколько осталось?',whole,F(2,5),'−','Выдели одно целое для вычитания.'),expr(f'{whole+1} − {a}/{d} = ?',whole+1,x,'−','Проверь обратным сложением.')]
        elif family=='mixed_operations':
            A=F(whole)+F(1,3);B=F(1)+F(1,2)
            tasks=[number(f'{whole} 1/3 = ? Запиши одной дробью.',A,'Целую часть умножь на 3, затем прибавь 1.'),expr(f'{whole} 1/3 + 1 1/2 = ?',A,B,'+','Можно перейти к неправильным дробям.'),expr(f'{whole} 1/3 − 1 1/2 = ?',A,B,'−','При недостатке долей займи единицу у целой части.'),choice('Вычисли 3 1/4 − 1 3/4.','1 1/2',['2 1/2','1 1/2','2 2/4'],'3 1/4 = 2 5/4.'),expr(f'Было {whole} 1/3 кг материала. Добавили 1/6 кг. Сколько стало?',A,F(1,6),'+','Единицы массы одинаковы.'),expr(f'{whole+1} 1/2 − 2/3 = ?',F(whole+1)+F(1,2),F(2,3),'−','Приведи дробные части к шестым.')]
        elif family=='multiply':
            tasks=[number('Половина от половины — какая доля целого?',F(1,4),'Раздели половину ещё на две равные части.',model=fraction(1,4)),expr(f'{f(aa)} × {f(cc)} = ?',aa,cc,'×','Перемножь числители и знаменатели.'),expr(f'{v+2} × 2/3 = ?',v+2,F(2,3),'×','Натуральное число можно записать со знаменателем 1.'),expr(f'{whole} 1/2 × 2 = ?',F(whole)+F(1,2),2,'×','Сначала смешанное число переведи в неправильную дробь.'),choice('При умножении 2/3 на 1/2 результат…','Меньше 2/3',['Больше 2/3','Меньше 2/3','Равен 2/3'],'Умножение на положительную дробь меньше 1 уменьшает число.'),expr(f'Стороны прямоугольника {f(aa)} м и {f(cc)} м. Площадь в м²?',aa,cc,'×','Площадь равна произведению сторон.')]
        elif family=='reciprocal':
            tasks=[number(f'Найди число, обратное {v+2}.',F(1,v+2),'Произведение взаимно обратных чисел равно 1.'),number(f'Найди число, обратное {a}/{d}.',F(d,a),'Поменяй числитель и знаменатель местами.'),number(f'Найди число, обратное {whole} 1/2.',1/(F(whole)+F(1,2)),'Сначала перейди к неправильной дроби.'),choice('Есть ли число, обратное нулю?','Нет',['Да','Нет'],'Нуль при умножении не может дать 1.'),number('Какое число обратно самому себе среди положительных чисел?',1,'Его квадрат должен быть равен 1.'),expr(f'{f(aa)} × {f(1/aa)} = ?',aa,1/aa,'×','Это проверка пары взаимно обратных чисел.')]
        else:
            tasks=[number('Сколько половинок содержится в 2 целых?',4,'Деление показывает, сколько раз одна величина содержится в другой.',model=fraction(4,2)),expr(f'{f(aa)} ÷ {f(cc)} = ?',aa,cc,'÷','Умножь делимое на число, обратное делителю.'),expr(f'{whole} ÷ 1/2 = ?',whole,F(1,2),'÷','Деление на половину удваивает число.'),expr(f'{whole} 1/2 ÷ 3/2 = ?',F(whole)+F(1,2),F(3,2),'÷','Преобразуй смешанное число перед действием.'),choice('При делении 3/4 на 1/2 нужно…','Умножить 3/4 на 2',['Умножить 3/4 на 1/2','Умножить 3/4 на 2','Перевернуть обе дроби'],'Обратной заменяют только дробь-делитель.'),expr(f'Ленту длиной {whole} м режут на части по 1/4 м. Сколько частей?',whole,F(1,4),'÷','Раздели общую длину на длину одной части.')]
        notes={'add_same':['При одинаковых знаменателях действуют с числителями.','Знаменатель сохраняется: размер доли не меняется.'],'add_different':['Сначала приведи дроби к общему знаменателю.','Затем выполни действие с числителями и сократи результат.'],'subtract_natural':['Для вычитания дроби представь единицу как n/n.','При необходимости выдели одно целое из натурального числа.'],'mixed_operations':['Можно отдельно работать с целой и дробной частями или перейти к неправильным дробям.','Если дробной части не хватает для вычитания, займи единицу у целой части.'],'multiply':['Умножай числитель на числитель, знаменатель на знаменатель.','Смешанные числа предварительно переводи в неправильные дроби.'],'reciprocal':['Произведение взаимно обратных чисел равно 1.','У нуля нет обратного числа.'],'divide':['Деление на ненулевую дробь заменяют умножением на обратную ей.','Переворачивают делитель, а не делимое.']}
        examples={'add_same':['1/5 + 2/5','(1 + 2)/5 = 3/5.'],'add_different':['1/2 + 1/3','3/6 + 2/6 = 5/6.'],'subtract_natural':['3 − 2/5','2 + 5/5 − 2/5 = 2 3/5.'],'mixed_operations':['3 1/4 − 1 3/4','2 5/4 − 1 3/4 = 1 2/4 = 1 1/2.'],'multiply':['2/3 × 3/4','6/12 = 1/2.'],'reciprocal':['Обратное для 2/3','3/2, потому что 2/3 × 3/2 = 1.'],'divide':['3/4 ÷ 1/2','3/4 × 2 = 3/2 = 1 1/2.']}
        return package({'add_same':'Складываем одинаковые доли','add_different':'Приведи доли к одному размеру','subtract_natural':'Одолжи целое','mixed_operations':'Собери целые и доли','multiply':'Доля от доли','reciprocal':'Найди обратную пару','divide':'Сколько долей поместится?'}[family],notes[family],examples[family],'Составь свою задачу по теме. Запиши решение и проверь его обратным действием.',tasks)
    raise ValueError(family)
